// Fundamental arguments (Simon et al. 1994), radians.
inline void fundamental_args(double t, double a[5]) {
    const std::array<double,5>* polys[5] = {&fa_l_moon, &fa_l_sun, &fa_F, &fa_D, &fa_Om};
    for (int k = 0; k < 5; ++k) {
        const auto& P = *polys[k];
        double v = P[4];
        for (int i = 3; i >= 0; --i) v = v * t + P[i];
        double red = std::fmod(v, kAsec360);
        if (red < 0.0) red += kAsec360;
        a[k] = red * kAsec2Rad;
    }
}

// IAU 2000B nutation: (dpsi, deps) in radians. 2-term fundamental arguments,
// 77 luni-solar terms, fixed offsets; planetary terms are zero by construction.
inline void iau2000b_rad(double jd_tt, double& dpsi, double& deps) {
    const double t = (jd_tt - 2451545.0) / 36525.0;
    double a[5];
    fundamental_args(t, a);
    double s = 0.0, e = 0.0;
    for (int i = 0; i < 77; ++i) {
        double arg = 0.0;
        for (int k = 0; k < 5; ++k) arg += nals[i][k] * a[k];
        const double sn = std::sin(arg), cs = std::cos(arg);
        s += sn * lonc[i][0] + sn * lonc[i][1] * t + cs * lonc[i][2];
        e += cs * oblc[i][0] + cs * oblc[i][1] * t + sn * oblc[i][2];
    }
    s += -0.000135e7;   // fixed IAU 2000B offsets, tenths of uas
    e +=  0.000388e7;
    constexpr double kTenthUas2Rad = kAsec2Rad / 1e7;
    dpsi = s * kTenthUas2Rad;
    deps = e * kTenthUas2Rad;
}

// Equation-of-the-equinoxes complementary terms, radians (Capitaine et al. 2003,
// Table 3 — the 33-term series skyfield evaluates for GAST).
inline double eqeq_complementary_rad(double jd_tt) {
    const double t = (jd_tt - 2451545.0) / 36525.0;
    double fa[14];
    fa[0] = 2.35555598 + 8328.6914269554 * t;
    fa[1] = 6.24006013 + 628.301955 * t;
    fa[2] = 1.627905234 + 8433.466158131 * t;
    fa[3] = 5.198466741 + 7771.3771468121 * t;
    fa[4] = 2.18243920 + (-33.757045) * t;
    fa[5] = 4.402608842 + 2608.7903141574 * t;
    fa[6] = 3.176146697 + 1021.3285546211 * t;
    fa[7] = 1.753470314 + 628.3075849991 * t;
    fa[8] = 6.203480913 + 334.0612426700 * t;
    fa[9] = 0.599546497 + 52.9690962641 * t;
    fa[10] = 0.874016757 + 21.3299104960 * t;
    fa[11] = 5.481293872 + 7.4781598567 * t;
    fa[12] = 5.311886287 + 3.8133035638 * t;
    fa[13] = (0.024381750 + 0.00000538691 * t) * t;
    for (int i = 0; i < 14; ++i) {
        fa[i] = std::fmod(fa[i], kTau);
        if (fa[i] < 0.0) fa[i] += kTau;
    }
    double c = 0.0;
    for (int i = 0; i < 33; ++i) {
        double arg = 0.0;
        for (int k = 0; k < 14; ++k) arg += ke0[i][k] * fa[k];
        c += se0[i] * std::sin(arg) + se1[i] * std::cos(arg);
    }
    return c * kAsec2Rad;
}

// Mean obliquity of date, radians (Capitaine et al. 2003, eq. 39).
inline double mean_obliquity_rad(double jd_tdb) {
    const double t = (jd_tdb - 2451545.0) / 36525.0;
    const double eps_arcsec = (((( -0.0000000434 * t - 0.000000576) * t
        + 0.00200340) * t - 0.0001831) * t - 46.836769) * t + 84381.406;
    return eps_arcsec * kAsec2Rad;
}

// Capitaine et al. (2003) 4-angle precession matrix — verbatim port of
// skyfield's precessionlib.compute_precession: P = R3(chia) R1(-omegaa) R3(-psia) R1(eps0).
inline void precession_matrix(double jd_tdb, double P[3][3]) {
    const double t = (jd_tdb - 2451545.0) / 36525.0;
    const double eps0 = 84381.406 * kAsec2Rad;
    double psia = ((((-0.0000000951 * t + 0.000132851) * t - 0.00114045) * t
        - 1.0790069) * t + 5038.481507) * t;
    double omegaa = ((((+0.0000003337 * t - 0.000000467) * t
        - 0.00772503) * t + 0.0512623) * t - 0.025754) * t + 84381.406;
    double chia = ((((-0.0000000560 * t + 0.000170663) * t - 0.00121197) * t
        - 2.3814292) * t + 10.556403) * t;
    psia *= kAsec2Rad; omegaa *= kAsec2Rad; chia *= kAsec2Rad;
    const double sa = std::sin(eps0), ca = std::cos(eps0);
    const double sb = std::sin(-psia), cb = std::cos(-psia);
    const double sc = std::sin(-omegaa), cc = std::cos(-omegaa);
    const double sd = std::sin(chia), cd = std::cos(chia);
    // NOTE: rot3 below is assembled exactly like skyfield's array.
    P[0][0] = cd * cb - sb * sd * cc;
    P[0][1] = cd * sb * ca + sd * cc * cb * ca - sa * sd * sc;
    P[0][2] = cd * sb * sa + sd * cc * cb * sa + ca * sd * sc;
    P[1][0] = -sd * cb - sb * cd * cc;
    P[1][1] = -sd * sb * ca + cd * cc * cb * ca - sa * cd * sc;
    P[1][2] = -sd * sb * sa + cd * cc * cb * sa + ca * cd * sc;
    P[2][0] = sb * sc;
    P[2][1] = -sc * cb * ca - sa * cc;
    P[2][2] = -sc * cb * sa + cc * ca;
}

// Nutation matrix N from mean/true obliquity and dpsi — verbatim port of
// skyfield's build_nutation_matrix(mean_obliquity, true_obliquity, psi).
inline void nutation_matrix(double mean_ob, double true_ob, double psi, double N[3][3]) {
    const double cobm = std::cos(mean_ob), sobm = std::sin(mean_ob);
    const double cobt = std::cos(true_ob), sobt = std::sin(true_ob);
    const double cpsi = std::cos(psi), spsi = std::sin(psi);
    N[0][0] = cpsi;
    N[0][1] = -spsi * cobm;
    N[0][2] = -spsi * sobm;
    N[1][0] = spsi * cobt;
    N[1][1] = cpsi * cobm * cobt + sobm * sobt;
    N[1][2] = cpsi * sobm * cobt - cobm * sobt;
    N[2][0] = spsi * sobt;
    N[2][1] = cpsi * cobm * sobt - sobm * cobt;
    N[2][2] = cpsi * sobm * sobt + cobm * cobt;
}

// Full ICRF -> true-equator-and-equinox-of-date rotation M = N @ P.
inline void tete_matrix(double jd_tt, double jd_tdb, double M[3][3]) {
    double P[3][3], N[3][3];
    precession_matrix(jd_tdb, P);
    double dpsi, deps;
    iau2000b_rad(jd_tt, dpsi, deps);
    const double mean_ob = mean_obliquity_rad(jd_tdb);
    nutation_matrix(mean_ob, mean_ob + deps, dpsi, N);
    for (int i = 0; i < 3; ++i)
        for (int j = 0; j < 3; ++j) {
            double v = 0.0;
            for (int k = 0; k < 3; ++k) v += N[i][k] * P[k][j];
            M[i][j] = v;
        }
}

// ICRS -> J2000 frame-bias matrix B (skyfield framelib.ICRS_to_J2000).
// Without it every ecliptic longitude is ~7 mas off — exactly the residual
// we chased for a day before finding this line in skyfield's Time.M.
inline void frame_bias_matrix(double B[3][3]) {
    B[0][0] = 1.0;              B[0][1] = -7.07827974e-08;  B[0][2] = 8.05614894e-08;
    B[1][0] = 7.07827974e-08;   B[1][1] = 1.0;              B[1][2] = 3.30604145e-08;
    B[2][0] = -8.05614894e-08;  B[2][1] = -3.30604145e-08;  B[2][2] = 1.0;
}

// Greenwich Mean/Apparent Sidereal Time, degrees — verbatim port of
// skyfield's earthlib.sidereal_time + timelib.gast:
//   theta = ERA(jd_ut1); st = (0.014506 + ((((-0.0000000368*t - 0.000029956)*t
//           - 0.00000044)*t + 1.3915817)*t + 4612.156534)*t)   [arcsec]
//   gmst_hours = (st/54000 + theta*24) % 24
//   gast_hours = (gmst + (dpsi*cos(mean_ob) + complementary)/tau*24) % 24
inline double earth_rotation_angle(double jd_ut1) {
    const double th = 0.7790572732640 + 0.00273781191135448 * (jd_ut1 - 2451545.0);
    double v = std::fmod(th, 1.0) + std::fmod(jd_ut1, 1.0);
    v = std::fmod(v, 1.0);
    if (v < 0.0) v += 1.0;
    return v;   // fraction of a whole rotation
}
inline double gmst_deg_full(double jd_tt, double jd_ut1) {
    const double theta = earth_rotation_angle(jd_ut1);
    const double t = (jd_tt - 2451545.0) / 36525.0;   // tdb ~= tt here
    const double st = 0.014506 +
        (((( -0.0000000368 * t - 0.000029956) * t - 0.00000044) * t
          + 1.3915817) * t + 4612.156534) * t;   // arcseconds
    double gmst_h = st / 54000.0 + theta * 24.0;
    gmst_h = std::fmod(gmst_h, 24.0);
    if (gmst_h < 0.0) gmst_h += 24.0;
    return gmst_h * 15.0;
}
inline double gast_deg_full(double jd_tt, double jd_ut1) {
    const double gmst_h = gmst_deg_full(jd_tt, jd_ut1) / 15.0;
    double dpsi, deps;
    iau2000b_rad(jd_tt, dpsi, deps);
    const double mean_ob = mean_obliquity_rad(jd_tt);
    const double eqeq = dpsi * std::cos(mean_ob) + eqeq_complementary_rad(jd_tt);
    constexpr double kTau = 6.28318530717958647692;
    double gast_h = gmst_h + eqeq / kTau * 24.0;
    gast_h = std::fmod(gast_h, 24.0);
    if (gast_h < 0.0) gast_h += 24.0;
    return gast_h * 15.0;
}
